mapper.select:
SELECT OPTION_ID AS OPTIONID , CHART_ID AS CHARTID , SERIES_TYPE AS SERIESTYPE , SERIES_KEY AS SERIESKEY , SERIES_LABEL AS SERIESLABEL , SERIES_PERIOD AS SERIESPERIOD , SERIES_COLOR AS SERIESCOLOR , LINE_WIDTH AS LINEWIDTH , ENABLED_YN AS ENABLEDYN , DISPLAY_ORDER AS DISPLAYORDER , MODIFY_DATE AS MODIFYDATE , CREATE_DATE AS CREATEDATE FROM TB_S_CHART_OPTION WHERE 1 = 1
AND CHART_ID = #{chartId}
AND SERIES_TYPE = #{seriesType}
ORDER BY SERIES_PERIOD

mapper.update:
UPDATE TB_S_CHART_OPTION
   SET SERIES_LABEL  = #{seriesLabel}
     , SERIES_PERIOD = #{seriesPeriod}
     , SERIES_COLOR  = #{seriesColor}
     , LINE_WIDTH   = #{lineWidth, jdbcType=NUMERIC}
     , ENABLED_YN    = #{enabledYn}
     , DISPLAY_ORDER = #{displayOrder}
     , MODIFY_DATE   = SYSDATE
 WHERE CHART_ID     = #{chartId}
   AND SERIES_TYPE  = #{seriesType}
   AND SERIES_KEY   = #{seriesKey}

mapper.insert:
INSERT INTO TB_S_CHART_OPTION
(
      OPTION_ID
    , CHART_ID
    , SERIES_TYPE
    , SERIES_KEY
    , SERIES_LABEL
    , SERIES_PERIOD
    , SERIES_COLOR
    , LINE_WIDTH
    , ENABLED_YN
    , DISPLAY_ORDER
    , MODIFY_DATE
    , CREATE_DATE
)
VALUES
(
      SEQ_TB_S_CHART_OPTION.NEXTVAL
    , #{chartId}
    , #{seriesType}
    , #{seriesKey}
    , #{seriesLabel}
    , #{seriesPeriod}
    , #{seriesColor}
    , #{lineWidth, jdbcType=NUMERIC}
    , #{enabledYn}
    , #{displayOrder}
    , SYSDATE
    , SYSDATE
)

mapper.delete:
DELETE FROM TB_S_CHART_OPTION
 WHERE CHART_ID = #{chartId}
   AND SERIES_TYPE = #{seriesType}
